import json

class ETLJob:
    # Class attribute - shared by all instances
    default_retries = 3

    def __init__(self, name: str, source: str):
        # Instance attributes - unique per object
        self.name = name
        self.source = source
        self.retries = ETLJob.default_retries

    # Instance method - operates on self
    def describe(self) -> str:
        return f"{self.name} reads from {self.source}"

    # Class method - alternative constructor, respects subclasses via cls
    @classmethod
    def from_config(cls, cfg: dict) -> "ETLJob":
        return cls(name=cfg["name"], source=cfg["source"])

    # Static method - pure utility, no self/cls
    @staticmethod
    def is_valid_source(uri: str) -> bool:
        return uri.startswith(("s3://", "gs://", "file://"))

job = ETLJob.from_config({"name": "daily", "source": "s3://bucket/in"})
print(job.describe())
print(ETLJob.is_valid_source(job.source))

class DataSource:
    def __init__(self, uri: str):
        self.uri = uri

    def read(self):
        raise NotImplementedError

    def __repr__(self) -> str:
        return f"{type(self).__name__}(uri={self.uri!r})"

    def __eq__(self, other) -> bool:
        if not isinstance(other, DataSource):
            return NotImplemented
        return self.uri == other.uri

class S3Source(DataSource):
    def __init__(self, uri: str, region: str):
        super().__init__(uri)        # cooperative init of base
        self.region = region

    def read(self):
        return f"reading {self.uri} in {self.region}"

s = S3Source("s3://b/k", "us-east-1")
print(repr(s))
print(s == S3Source("s3://b/k", "eu-west-1"))

from dataclasses import dataclass, field

@dataclass(frozen=True)
class TableSchema:
    name: str
    columns: list = field(default_factory=list)  # safe mutable default

class Table:
    def __init__(self, schema: TableSchema, row_count: int = 0):
        self.schema = schema      # composition: Table HAS-A schema
        self.row_count = row_count

    @property
    def row_count(self) -> int:
        return self._row_count

    @row_count.setter
    def row_count(self, value: int) -> None:
        if value < 0:
            raise ValueError("row_count must be non-negative")
        self._row_count = value

t = Table(TableSchema("events", ["id", "ts"]), row_count=10)
print(t.schema)
t.row_count = 25      # validated via setter
print(t.row_count)
